import{_ as m,l as n,o as e,c as s,v as a,p as i,x as o,d as l,i as f,S as h}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"Performer 原文","description":"","frontmatter":{"title":"Performer 原文","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/choromanski-performer.md","filePath":"llm/choromanski-performer.md","lastUpdated":1789023840000}'),E={name:"llm/choromanski-performer.md"};function p(d,r,A,P,B,c){const t=n("Mermaid");return e(),s("div",null,[r[1]||(r[1]=a('<h1 id="performer-原文" tabindex="-1">Performer 原文 <a class="header-anchor" href="#performer-原文" aria-label="Permalink to &quot;Performer 原文&quot;">​</a></h1><div class="epigraph"><p>Performer 用可证明精度去估计满秩 softmax 注意力，却只要线性的时间与空间，并且不依赖稀疏或低秩先验。</p><footer>—— Choromanski 等，Rethinking Attention with Performers，ICLR 2021</footer></div><p>Choromanski、Likhosherstov、Dohan、Song、Gane、Sarlós、Hawkins、Davis、Mohiuddin、Kaiser、Belanger、Colwell 与 Weller 的 ICLR 2021 论文，要回答的不是「核特征能不能让注意力线性」——<a href="/llm/katharopoulos-linear">Katharopoulos 的线性 Transformer</a> 已经换过核——而是：<strong>能否在期望上逼近真正的 softmax 核，并给出方差与一致收敛，使这项近似可以当科学研究的工具，而不只是又一种加速技巧。</strong> FAVOR+（Fast Attention Via Positive Orthogonal Random Features）是他们为 softmax 核设计的随机特征；Performer 是套上这套特征的 Transformer。机制专文见 <a href="/llm/performer-favor">Performer / FAVOR+</a>。本篇写原文作为一篇理论+系统论文交了什么实验、比了谁、没承诺什么。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>2020 年的高效注意力两条主流路都有先验。稀疏图（Longformer、BigBird、Reformer 的 LSH）假定重要边落在窗口、全局点或哈希桶里；低秩投影（Linformer）假定注意力矩阵有一个与长度无关的秩。两条路都能跑更长序列，但改变了模型类：不是在估计原来的 \\(A=\\mathrm{softmax}(QK^\\top/\\sqrt{d})\\)，而是在另一个函数类里训练。论文要的是第三条：保持与常规 Transformer 兼容，注意力矩阵满秩可估，复杂度对长度线性，先验只来自随机特征的蒙特卡洛，不来自「哪些位置可以看」。</p><p>softmax 核 \\(\\exp(q^\\top k)\\) 不是平移不变的高斯核，普通随机傅里叶特征会出负分量，归一化后权重可翻号。蛋白质、像素序列又把长度推到常规 Transformer 显存墙之外，使得「softmax 对其他核到底好不好」无法在同一尺度上比。作者需要一种正值、正交、对 softmax 无偏（或近无偏）的特征，才能第一次在 ImageNet64 与 TrEMBL 这种长度上把核当成自变量。</p><h3 id="论文真正卖的是可证近似-不是「更快的-bert」" tabindex="-1">论文真正卖的是可证近似，不是「更快的 BERT」 <a class="header-anchor" href="#论文真正卖的是可证近似-不是「更快的-bert」" aria-label="Permalink to &quot;论文真正卖的是可证近似，不是「更快的 BERT」&quot;">​</a></h3><p>标题 <em>Rethinking Attention</em> 针对的是注意力矩阵的定义，不是 GLUE 刷分。理论条款包括：注意力矩阵的无偏或近无偏估计、一致收敛、低估计方差。FAVOR+ 被写成也可用于其他可核化注意力，从而在大规模任务上比较 softmax 与 ReLU 等核。把这篇读成「工业界应用该立刻换 Performer」，会错过它作为核方法论文的合同：特征维 \\(m\\) 是精度旋钮，实验必须报告 \\(m\\)，不能只报「线性注意力」。</p><p><span class="marginnote">先有 2020 年的蛋白质 MLM 预印本（<em>Masked Language Modeling for Proteins via Linearly Scalable Long-Context Transformers</em>），ICLR 终稿把方法收成 Performer / FAVOR+ 并补上 ImageNet64 与理论。引用会议版 2009.14794 / ICLR 2021，不要把两稿的层数表混用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实验跨像素预测、文本与蛋白质。机制上仍是正正交随机特征逼近 \\(\\exp(q^\\top k)\\)，再走线性注意力的结合律；公式与正交化步骤见专文。原文多出来的是对照协议。ImageNet64 无条件像素建模，长度 \\(L=12288\\)，常规 Transformer 不可行。各方法固定 \\((n_{\\mathrm{heads}},d_{\\mathrm{ff}},d)=(8,2048,512)\\)，只变层数：Performer 6 层对上 Reformer 12 层，Performer 12 层对上 Reformer 24 层。作者还写：视 TPU / GPU 与 JAX 实现，Performer 可比 Reformer 快约 2×（无条件设定）。这是「同样宽度下用层数换近似核」的对照，不是 FLOPs 严格对齐。</p><p>蛋白质用 2019 年 1 月 TrEMBL，36 层，\\((n_{\\mathrm{heads}},d_{\\mathrm{ff}},d)=(8,1024,512)\\)，16×16 TPU v2，batch 按显存最大化。对照 Reformer、Linformer。另做拼接蛋白质到 \\(L=8192\\) 的相互作用玩具任务：常规 Transformer 在每芯片 batch=1 仍 OOM，基线被迫缩到宽度 256、至多 3 层；Performer 用标准 \\((8,6,2048,512)\\)、每芯片 batch=8。小 Transformer 准确率停在约 19%，Performer 训到约 24%。这证明的是「线性近似让你能放下更大的模型」，不是 24% 已经解决蛋白质相互作用。</p>',12)),(e(),i(h,null,{default:o(()=>[f(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E8%AE%BA%E6%96%87%E5%91%BD%E9%A2%98%22%5D%20--%3E%20T%5B%22%E6%97%A0%E5%81%8F%2F%E4%BD%8E%E6%96%B9%E5%B7%AE%E4%BC%B0%E8%AE%A1%20softmax%20%E6%A0%B8%22%5D%0A%20%20P%20--%3E%20E%5B%22%E9%95%BF%E5%BA%8F%E5%88%97%E4%B8%8A%E6%AF%94%E8%BE%83%E6%A0%B8%EF%BC%8C%E8%80%8C%E4%B8%8D%E5%8F%AA%E6%AF%94%E8%BE%83%E7%A8%80%E7%96%8F%E5%9B%BE%22%5D%0A%20%20T%20--%3E%20FAVOR%5B%22FAVOR%2B%20%E6%AD%A3%E6%AD%A3%E4%BA%A4%E9%9A%8F%E6%9C%BA%E7%89%B9%E5%BE%81%22%5D%0A%20%20E%20--%3E%20IMG%5B%22ImageNet64%20L%3D12288%22%5D%0A%20%20E%20--%3E%20PROT%5B%22TrEMBL%20%E4%B8%8E%E6%8B%BC%E6%8E%A5%20L%3D8192%22%5D%0A%20%20FAVOR%20--%3E%20PERF%5B%22Performer%20%E6%9E%B6%E6%9E%84%22%5D%0A%20%20IMG%20--%3E%20PERF%0A%20%20PROT%20--%3E%20PERF%0A"})]),fallback:o(()=>[...r[0]||(r[0]=[l(" Loading... ",-1)])]),_:1})),r[2]||(r[2]=a('<h3 id="与-reformer、linformer、确定核线性注意力" tabindex="-1">与 Reformer、Linformer、确定核线性注意力 <a class="header-anchor" href="#与-reformer、linformer、确定核线性注意力" aria-label="Permalink to &quot;与 Reformer、Linformer、确定核线性注意力&quot;">​</a></h3><p>Reformer 用 LSH 把相似查询键分桶，复杂度带大常数，短序列往往不快；它改变连通性。Linformer 把键值投影到固定长度，近似与内容无关，论文批评这会伤上下文。Katharopoulos 的 \\(\\phi=\\mathrm{elu}+1\\) 是确定特征，不声称逼近 softmax。Performer 的对照轴是：在不能跑满 softmax 的长度上，随机特征是否仍接近「假如能跑 softmax 会得到的模型」，以及 ReLU 核 Performer 是否有时更好。后一点是原文明确写进贡献的：第一次有工具在超长任务上比核，而不是只能在短句上比。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>随机特征把 \\(\\exp(q^\\top k)\\) 写成 \\(\\mathbb{E}[\\phi(q)^\\top\\phi(k)]\\)。有限 \\(m\\) 下误差有两项：核值估计误差，以及 softmax 式行归一化带来的偏差——无偏针对的是核，不是行随机矩阵。正交化降低方向采样方差，使较小 \\(m\\) 可用。这些机制专文已写；原文还强调 <strong>均匀收敛</strong>：要以高概率在所有查询–键对上同时控误差，才能保证整层注意力图不在某几个位置炸开。这对深层残差网是合同，对单层核回归则过于强。</p><p>兼容常规 Transformer 意味着：同一套 \\(Q,K,V\\) 投影，只换注意力核的估计算子；可以插入已有 BERT/GPT 式堆叠。因果情形用前缀扫描，随机方向 \\(\\omega\\) 必须在训练与推理间冻结，否则状态错位——这是部署条款，原文用「与常规 Transformer 完全兼容」概括，工程上要自己固化种子。</p><p><span class="marginnote">论文写「不依赖稀疏或低秩先验」。实现上 \\(m\\ll n\\) 时估计矩阵的秩至多 \\(m\\)，看起来像低秩。先验指的是不对 \\(A\\) 的支撑或谱做结构假设；有限特征的秩是蒙特卡洛的后果，不是 Linformer 那种与内容无关的投影设计。</span></p><h3 id="蛋白质与像素为什么适合当主场" tabindex="-1">蛋白质与像素为什么适合当主场 <a class="header-anchor" href="#蛋白质与像素为什么适合当主场" aria-label="Permalink to &quot;蛋白质与像素为什么适合当主场&quot;">​</a></h3><p>TrEMBL 序列长、局部化学与长程接触同时存在，稀疏窗口会切掉接触图，低秩投影不区分残基。像素栅格 \\(64\\times 64\\times 3\\) 展成一万两千步，是当时 softmax 显存的刑具。语言建模短句上，Flash 式精确 softmax 后来把「线性」的墙钟优势吃掉；原文的实验年份里，对手是 Reformer 与 Linformer，不是 FlashAttention。读 2021 年的 2× Reformer，不要写成 2026 年相对 FA2 的加速。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><h3 id="、尖峰任务与外推" tabindex="-1">\\(m\\)、尖峰任务与外推 <a class="header-anchor" href="#、尖峰任务与外推" aria-label="Permalink to &quot;$m$、尖峰任务与外推&quot;">​</a></h3><p>特征维不够，近似核变平，针测与精确拷贝会输给真 softmax。原文主表不是针测。正交随机特征与 RoPE 叠用时，方向是在旋转后空间采的，长度外推误差可能被误诊为位置编码失败。混合精度下 \\(\\exp\\) 特征易溢出，需先按 \\(1/\\sqrt{d}\\) 缩放。短序列上 FAVOR+ 没有必要。把 Performer 当 BERT 替代而不调 \\(m\\)、不冻 \\(\\omega\\)，是误用论文。</p><p>理论保证是随机特征误差，不是下游任务最优。ReLU 核在某些蛋白质设定更好，说明「必须逼近 softmax」并非实验结论；结论是「终于能在同一线性算法下比核」。工业检索、代码拷贝仍应默认精确 softmax，除非长度强迫换核并单独报召回。</p><p><span class="marginnote">出处：Choromanski et al.，<em>Rethinking Attention with Performers</em>，ICLR 2021，arXiv:2009.14794。算法细节见本目录 Performer / FAVOR+ 专文；不要两篇互相复制公式段。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ICLR 2021 的 Performer 用 FAVOR+ 在线性复杂度下估计满秩 softmax 注意力，并给出无偏性与方差条款。</li><li>主场是 ImageNet64（\\(L=12288\\)）与 TrEMBL / 拼接蛋白质；用层数与能否放下模型对照 Reformer，而不是对照后来的 Flash。</li><li>确定核线性注意力、LSH 稀疏、低秩投影是不同先验；原文要去掉的是后两种结构假设。</li><li>有限 \\(m\\) 下权重仍有偏，尖峰任务不是卖点。</li><li>出处：Choromanski et al.，ICLR 2021。</li></ul>',15))])}const x=m(E,[["render",p]]);export{T as __pageData,x as default};
